+	const buffer = Buffer.alloc(
+		Math.min(stat.size, PROJECT_FILE_READ_LIMIT_BYTES),
+	);
+	const fd = openSync(path, "r");
+	try {
+		readSync(fd, buffer, 0, buffer.length, 0);
+	} finally {
+		closeSync(fd);
+	}
